# Firmas (magic numbers) de la tabla del tema: primeros bytes
FIRMAS = {b'\xFF\xD8\xFF': 'JPG', b'\x89PNG': 'PNG', b'GIF8': 'GIF',
          b'PK\x03\x04': 'ZIP/DOCX/XLSX', b'MZ': 'EXE',
          b'%PDF': 'PDF', b'ID3': 'MP3'}

def tipo_real(contenido):
    for firma, tipo in FIRMAS.items():
        if contenido.startswith(firma):   # ¿empieza por la firma?
            return tipo
    return 'sin firma (¿texto plano?)'

# Contenidos fabricados: nombre con el que se guardó -> bytes
pendrive = {
    'lista_compra.txt': b'%PDF-1.6\n...planos de la fabrica...',
    'notas.txt': b'\xFF\xD8\xFF\xE0\x00\x10JFIF\x00...',
    'informe.docx': b'PK\x03\x04\x14\x00\x06\x00...',
    'leeme.txt': b'Recordar comprar pan',
}
for nombre, datos in pendrive.items():
    print(f'{nombre:17} {datos[:4].hex(" ").upper():12}',
          '->', tipo_real(datos))
